# Scientific redesign: migration, frozen programs and adaptive reduction cost.
source('8-Visualization/scripts/render_fig5_three_rows_20261101_v10.R')
OUT12<-'8-Visualization/refinements/fig5_transfer_20261103_v12';R12<-'5-ClassifierValidation/runs/bulk-rnaseq__20261103_external_programs_v1';old11<-'8-Visualization/refinements/fig5_integrated_20261101_v11'
p12<-function(...)file.path(OUT12,...);rr<-function(n)fread(file.path(R12,'tables',paste0(n,'.csv')))
eff<-rr('program_effects');cov12<-rr('coverage');cf12<-fromJSON('5-ClassifierValidation/config/external_programs_20261103.json')
proglabels<-c('Bile-acid metabolism','Fatty-acid metabolism','Oxidative phosphorylation','Notch signaling','E2F targets','G2M checkpoint','Hypoxia','Glycolysis','EMT')
cohs<-sort(unique(eff$Cohort));short12<-c('Andersen','Sia','Jus P1','Jus P2','Job','TIGER');names(short12)<-cohs
manifest12<-list();save12<-function(id,stem,plot,w,h,track='Main'){dir<-if(track=='Main')'figures' else 'supplement';f<-p12(dir,stem);draw<-function(){if(is.function(plot))plot() else print(plot)};cairo_pdf(paste0(f,'.pdf'),width=w/25.4,height=h/25.4,family='Arial');draw();dev.off();svglite::svglite(paste0(f,'.svg'),width=w/25.4,height=h/25.4);draw();dev.off();ragg::agg_png(paste0(f,'.png'),width=w,height=h,units='mm',res=300,background='white');draw();dev.off();system2('pdftoppm',c('-png','-singlefile','-r','120',shQuote(paste0(f,'.pdf')),shQuote(p12('review/pdf_rendered',stem))));manifest12[[id]]<<-data.table(Panel=id,Track=track,PDF=paste0(f,'.pdf'),SVG=paste0(f,'.svg'),PNG=paste0(f,'.png'),WidthMM=w,HeightMM=h,Status='REVIEW_NOT_FINALIZED');cat('Rendered',id,'\n')}
copy12<-function(id,src,w,h,stem,track='Supplement'){dir<-if(track=='Main')'figures' else 'supplement';dest<-p12(dir,paste0(stem,'.pdf'));stopifnot(file.copy(src,dest,overwrite=TRUE));pngsrc<-sub('[.]pdf$','.png',src);if(!file.exists(pngsrc))pngsrc<-file.path(old11,'review',paste0(tools::file_path_sans_ext(basename(src)),'.png'));if(file.exists(pngsrc))file.copy(pngsrc,sub('[.]pdf$','.png',dest),overwrite=TRUE) else system2('pdftoppm',c('-png','-singlefile','-r','300',shQuote(dest),shQuote(sub('[.]pdf$','',dest))));manifest12[[id]]<<-data.table(Panel=id,Track=track,PDF=dest,SVG='',PNG=sub('[.]pdf$','.png',dest),WidthMM=w,HeightMM=h,Status='REVIEW_NOT_FINALIZED');cat('Copied',id,'\n')}
# A retains the explicit v11 training-fold/full-development distinction.
drawA12<-function(){canvas(174,32)
 vr(14,16,26,29,'#F1F5F8','#DCE4EA');vt('Data',14,27,7,TRUE,'centre');vt('497 principal tumors',14,21,6,FALSE,'centre');vt('Expression + labels',14,16.5,5.8,FALSE,'centre');for(j in 1:3){vr(6+(j-1)*8,10.5,7,2.7,FIG5_SUBTYPE[j]);vt(paste0('C',j),6+(j-1)*8,6.5,5.8,FALSE,'centre')}
 vr(77,23,87,14,'#F1F5F8','#DCE4EA');vt('Training-fold evaluation',77,27.5,7,TRUE,'centre');vt('Study correction → limma / RF / LASSO → consensus → SVM',77,22.5,5.7,FALSE,'centre');vt('Outer 5-fold × 5 repeats; inner 4-fold',77,18,5.7,FALSE,'centre')
 vr(77,7.5,87,13,'#F1F5F8','#DCE4EA');vt('All 497 tumors → 114-gene consensus SVM',77,10.5,6.8,TRUE,'centre');vt('Separate full-development fit',77,5,5.8,FALSE,'centre')
 vr(150,23,45,14,'#F1F5F8','#DCE4EA');vt('OOF and study-held-out transfer',150,25.5,6,FALSE,'centre');vt('Training-only gene selection',150,20,5.8,FALSE,'centre')
 vr(150,7.5,45,13,'#F1F5F8','#DCE4EA');vt('Fixed-model projection',150,10.5,6.3,TRUE,'centre');vt('506 microarray samples',150,5,5.8,FALSE,'centre')
 for(y in c(23,7.5)){vl(c(27.5,33),c(y,y),arrow=TRUE);vl(c(121,127),c(y,y),arrow=TRUE)};popViewport()}
 save12('A','Figure5A_workflow',drawA12,174,32)
drawB12<-function(){canvas(70,64);d<-fread(v8_path('source_data/B_subtype_gene_order.csv'));vt('Selection stability',1,61.5,7.5,TRUE);x0<-11;cw<-56/114;d[,X:=x0+(DisplayOrder-.5)*cw+(SubtypeGroup-1)*.7]
 for(j in 1:3){z<-d[SubtypeGroup==j];l<-min(z$X)-cw/2;r<-max(z$X)+cw/2;vr((l+r)/2,55,r-l,4,adjustcolor(FIG5_SUBTYPE[j],alpha.f=.15));vt(sprintf('C%d | %d',j,nrow(z)),(l+r)/2,55,6,TRUE,'centre')}
 vt('Outer-training selection (25 fits)',x0,49,6.4,TRUE);for(v in c(0,.5,1)){y<-27+18*v;vl(c(x0,69),c(y,y),'#E3E8EC');vt(sprintf('%d%%',100*v),x0-1,y,5.6,FALSE,'right')};for(i in 1:114){y<-27+18*d$ConsensusFraction[i];vl(rep(d$X[i],2),c(27,y),'#A7BCCB',.4);vp(d$X[i],y,size=.5)}
 vt('Full-development method support',x0,22,5.7);for(j in 1:3){yy<-18.8-(j-1)*2.3;vt(c('limma','RF','LASSO')[j],x0-1,yy,5.5,FALSE,'right');for(i in 1:114)vr(d$X[i],yy,cw-.03,1.8,if(d[[c('LimmaFull','RFFull','LASSOFull')[j]]][i])FIG5_INK else '#E7EDF1')}
 # Two pre-existing expression-representative names per subtype; no added selection.
 vt('Expression representatives',1,9.5,5.7);vt('C1: CPN2, TF',1,5,5.6,col=FIG5_SUBTYPE[1]);vt('C2: B4GALNT4, ITIH5',25,5,5.6,col=FIG5_SUBTYPE[2]);vt('C3: SLC2A1, CDH3',49,5,5.6,col=FIG5_SUBTYPE[3]);popViewport()}
cm12<-fread(file.path(old11,'source_data/D_confusion.csv'));st12<-fread(file.path(old11,'source_data/D_study_transfer.csv'))
drawC12<-function(){canvas(100,64);vt('Internal performance and study transfer',1,61.5,7.5,TRUE);vt('OOF: n=497; BA 98.79%',1,56,6.1,TRUE);vt('LOSO: all seven studies',50,56,6.1,TRUE);ramp<-circlize::colorRamp2(c(0,1),c('#F0F5F8','#4E8DB1'))
 for(i in 1:3)for(j in 1:3){z<-cm12[Truth==paste0('C',i)&Prediction==paste0('C',j)];x<-13+(j-.5)*10;y<-18+(3-i+.5)*10;vr(x,y,9.7,9.7,ramp(z$RowFraction));vt(sprintf('%d\n%.1f%%',z$Freq,100*z$RowFraction),x,y,6,FALSE,'centre',if(z$RowFraction>.5)'white' else FIG5_INK)}
 for(j in 1:3){vt(paste0('C',j),13+(j-.5)*10,15.5,5.7,FALSE,'centre');vt(paste0('C',j),11,18+(3-j+.5)*10,5.7,FALSE,'right')};grid.text('Reference',unit(3,'native'),unit(33,'native'),rot=90,gp=gpar(fontfamily='Arial',fontsize=5.7,col=FIG5_INK));vt('Predicted',28,11,5.8,FALSE,'centre')
 xp<-function(v)77+(v-.84)/.16*21;for(v in c(.85,.9,.95,1)){vl(rep(xp(v),2),c(14,51),'#E2E8ED');vt(round(100*v),xp(v),11.5,5.5,FALSE,'centre')}
 for(i in 1:7){z<-st12[i];y<-49-(i-1)*5.3;vt(sprintf('%s (%d)',z$Study,z$N),50,y,5.6);vl(xp(c(z$OOF,z$LOSO)),c(y,y),'#9AAFBF',.7);vp(xp(z$OOF),y,'#8197A6',1.1,1);vp(xp(z$LOSO),y,size=1.1)}
 vt('BA (%)',98,7.5,5.6,FALSE,'right');vp(52,4,'#8197A6',1.1,1);vt('OOF',54,4,5.5);vp(66,4,size=1.1);vt('Held-out',68,4,5.5);vt('Transductive centering',1,4,5.5);popViewport()}
prep12<-function(d){d<-copy(d);d[,ProgramLabel:=factor(Program,levels=rev(cf12$programs),labels=rev(proglabels))];d[,CohortLabel:=factor(short12[Cohort],levels=short12)];d[,Class:=factor(Class,levels=c('C1','C2','C3'))];d}
lim12<-ceiling(max(abs(eff$G),na.rm=TRUE)*2)/2
heat12<-function(d,title){d<-prep12(d);ggplot(d,aes(CohortLabel,ProgramLabel,fill=G))+geom_tile(colour='white',linewidth=.35)+facet_wrap(~Class,nrow=1)+scale_fill_gradient2(low='#377EB8',mid='white',high='#CD5258',midpoint=0,limits=c(-lim12,lim12),name='Hedges g',na.value='#B7B7B7',guide=guide_colorbar(display='rectangles'))+labs(title=title,x=NULL,y=NULL)+v10_theme()+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(size=5.8,angle=40,hjust=1),axis.text.y=element_text(size=6.2),strip.text=element_text(size=7,face='bold'),panel.spacing=unit(3,'mm'),legend.position='right',legend.key.height=unit(3,'mm'),legend.key.width=unit(2,'mm'))}
summary12<-function(){canvas(174,17);s<-fread(file.path(old11,'source_data/E_summary.csv'));d<-fread(file.path(old11,'source_data/E_composition.csv'));vt('Projected counts',1,4.2,5.7,TRUE);vt('n; genes / 114',1,10,5.7);for(i in 1:6){z<-s[CohortOrder==i];x<-36+(i-1)*24.6;vt(short12[i],x,14.4,6,TRUE,'centre');vt(sprintf('%d; %d/114',z$N,z$MatchedFeatures),x,10,5.5,FALSE,'centre');cum<-0;for(j in 1:3){a<-d[CohortOrder==i&Prediction==paste0('C',j)];wid<-22*a$Fraction;vr(x-11+cum+wid/2,4.2,wid,3,FIG5_SUBTYPE[j]);vt(a$N,x-11+cum+wid/2,4.2,5.3,FALSE,'centre',if(j==2)FIG5_INK else 'white');cum<-cum+wid}};popViewport()}
