 xx<-function(v)6+(v+2.6)/2.9*48;vl(rep(xx(0),2),c(38,51),'#8294A2',.5);grid.lines(unit(rep(xx(-1),2),'native'),unit(c(38,51),'native'),gp=gpar(col='#8294A2',lwd=.6,lty=2));vt('−1 pp target',xx(-1),52.2,5.7,FALSE,'centre');vl(xx(100*c(del12$Lower95,del12$Upper95)),rep(44,2),FIG5_INK,1.1);vp(xx(100*del12$Estimate),44,size=1.8)
 for(v in c(-2,-1,0))vt(v,xx(v),35,5.7,FALSE,'centre');vt('BA-loss target not met',30,30,6.3,TRUE,'centre');vt('Genes selected in 25 outer fits',1,23.8,6,TRUE);vt('Median 23 [10–51]',1,19.5,5.8)
 freq<-ch12[,.N,by=K];for(i in 1:nrow(freq))for(j in 1:freq$N[i])vp(7+(freq$K[i]-10)/41*45,11+(j-1)*1.5,size=.75);vl(c(7,52),c(9,9),'#9CABBA',.4);for(v in c(10,30,51))vt(v,7+(v-10)/41*45,6.5,5.6,FALSE,'centre');vt('Fixed 17-gene candidate: S6K/L',1,2,5.6);popViewport()}
